function loadAnimation(file: string, scene: Scene | null): Animation | null {
    return new Promise((resolve, reject) => {
        if (!file.startsWith("assets/")) {
            reject("Animation file must be in assets folder.");
            return;
        }
        const fileData = file.slice(file.indexOf("assets/") + 11) as ArrayBuffer;
        const numFrames = 7 * file.length;
        const numFramesStr = numFrames.toString();
        if (animation.numFrames !== numFramesStr) {
            reject("The number of frames for the animation is not valid.");
            return;
        }
        let animation = new Animation(numFrames);
        animation.path = file;
        animation.getFrameData = () => {
            let frameData = new DataView(fileData).getUint8(0, false);
            if (frameData === 0x01) {
                let frames = new Uint8Array(frameData, 2, frameData.length - 2);
                scene = frameData instanceof DataView ? new Scene(frameData, frameData.length) : scene;
                animation.fromArrayFrames(frameData);
